INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 7, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", 0.0, 1, "2030/12/17 14:59:59", 106001, "キャル", 7001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 7, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", 0.0, 1, "2030/12/17 14:59:59", 105901, "コッコロ", 7002);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 7, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", 0.0, 1, "2030/12/17 14:59:59", 105801, "ペコリーヌ", 7003);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 10, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "ジュエルを食べ物…\nいえ、貴重品と交換できます！", 0.0, 1, "2030/12/17 14:59:59", 105801, "ペコリーヌ", 10001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 10, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", 0.0, 1, "2030/12/17 14:59:59", 106001, "キャル", 10002);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 10, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", 0.0, 1, "2030/12/17 14:59:59", 105901, "コッコロ", 10003);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 10, "2015/12/17 15:00:00", 2, -363.0, 0, 0.0, 2104010, "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", 0.0, 1, "2030/12/17 14:59:59", 106401, "シェフィ", 10004);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 12, "2015/12/17 15:00:00", 1, -416.5, 0, 0.0, 0, "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", 0.0, 1, "2030/12/17 14:59:59", 105801, "ペコリーヌ", 12001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 13, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", 0.0, 1, "2030/12/17 14:59:59", 106001, "キャル", 13001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 13, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", 0.0, 1, "2030/12/17 14:59:59", 105901, "コッコロ", 13002);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 13, "2015/12/17 15:00:00", 2, -363.0, 0, 0.0, 2104010, "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", 0.0, 1, "2030/12/17 14:59:59", 106401, "シェフィ", 13003);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 13, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", 0.0, 1, "2030/12/17 14:59:59", 105801, "ペコリーヌ", 13004);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 14, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", 0.0, 1, "2030/12/17 14:59:59", 105901, "コッコロ", 14001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 14, "2015/12/17 15:00:00", 2, -363.0, 0, 0.0, 2104010, "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", 0.0, 1, "2030/12/17 14:59:59", 106401, "シェフィ", 14002);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 14, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", 0.0, 1, "2030/12/17 14:59:59", 105801, "ペコリーヌ", 14003);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 14, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", 0.0, 1, "2030/12/17 14:59:59", 106001, "キャル", 14004);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 15, "2015/12/17 15:00:00", 1, -470.0, 0, 0.0, 0, "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", 0.0, 1, "2030/12/17 14:59:59", 105901, "コッコロ", 15001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 16, "2015/12/17 15:00:00", 2, -363.0, 0, 0.0, 2104010, "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", 0.0, 1, "2030/12/17 14:59:59", 106401, "シェフィ", 16001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 16, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", 0.0, 1, "2030/12/17 14:59:59", 105801, "ペコリーヌ", 16002);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 16, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", 0.0, 1, "2030/12/17 14:59:59", 106001, "キャル", 16003);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 16, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", 0.0, 1, "2030/12/17 14:59:59", 105901, "コッコロ", 16004);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 17, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", 0.0, 1, "2030/12/17 14:59:59", 105901, "コッコロ", 17002);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 25, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", 0.0, 1, "2030/12/17 14:59:59", 106001, "キャル", 17004);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 25, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", 0.0, 1, "2030/12/17 14:59:59", 105901, "コッコロ", 17005);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 25, "2015/12/17 15:00:00", 2, -363.0, 0, 0.0, 2104010, "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", 0.0, 1, "2030/12/17 14:59:59", 106401, "シェフィ", 17006);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 25, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", 0.0, 1, "2030/12/17 14:59:59", 105801, "ペコリーヌ", 17007);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 18, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", 0.0, 1, "2030/12/17 14:59:59", 190801, "カリン", 18001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 18, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！", 0.0, 1, "2030/12/17 14:59:59", 190801, "カリン", 18002);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (3, 19, "2015/12/17 15:00:00", 1, -470.0, 0, 0.0, 0, "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", 0.0, 1, "2030/12/17 14:59:59", 190801, "カリン", 19001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (4, 19, "2015/12/17 15:00:00", 1, -470.0, 0, 0.0, 0, "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", 0.0, 1, "2030/12/17 14:59:59", 190801, "カリン", 19002);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (5, 20, "2015/12/17 15:00:00", 1, -470.0, 0, 0.0, 0, "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", 0.0, 1, "2030/12/17 14:59:59", 190801, "カリン", 20001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (6, 20, "2015/12/17 15:00:00", 1, -470.0, 0, 0.0, 0, "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", 0.0, 1, "2030/12/17 14:59:59", 190801, "カリン", 20002);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 21, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", 0.0, 1, "2030/12/17 14:59:59", 106001, "キャル", 21001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 21, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", 0.0, 1, "2030/12/17 14:59:59", 105901, "コッコロ", 21002);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 21, "2015/12/17 15:00:00", 2, -363.0, 0, 0.0, 2104010, "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", 0.0, 1, "2030/12/17 14:59:59", 106401, "シェフィ", 21003);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 21, "2015/12/17 15:00:00", 1, -363.0, 0, 0.0, 0, "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", 0.0, 1, "2030/12/17 14:59:59", 105801, "ペコリーヌ", 21004);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 22, "2015/12/17 15:00:00", 1, -430.0, 0, 0.0, 0, "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", 0.0, 1, "2030/12/17 14:59:59", 190801, "カリン", 22001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 22, "2015/12/17 15:00:00", 1, -430.0, 0, 0.0, 0, "ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！", 0.0, 1, "2030/12/17 14:59:59", 190801, "カリン", 22002);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (3, 23, "2015/12/17 15:00:00", 1, -430.0, 0, 0.0, 0, "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", 0.0, 1, "2030/12/17 14:59:59", 190801, "カリン", 23001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (4, 23, "2015/12/17 15:00:00", 1, -430.0, 0, 0.0, 0, "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", 0.0, 1, "2030/12/17 14:59:59", 190801, "カリン", 23002);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 24, "2019/01/31 12:00:00", 1, -385.0, 10011, 4.08, 0, "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", 8.0, 2, "2030/12/17 14:59:59", 109001, "エリコ（バレンタイン）", 24001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 24, "2019/01/31 12:00:00", 1, -385.0, 10011, 5.0, 0, "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", 8.0, 2, "2030/12/17 14:59:59", 109001, "エリコ（バレンタイン）", 24002);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (3, 24, "2019/01/31 12:00:00", 1, -385.0, 10011, 10.11, 0, "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", 8.0, 2, "2030/12/17 14:59:59", 109001, "エリコ（バレンタイン）", 24003);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (4, 24, "2019/01/31 12:00:00", 1, -385.0, 10011, 4.0, 0, "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", 8.0, 2, "2030/12/17 14:59:59", 109001, "エリコ（バレンタイン）", 24004);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (5, 24, "2019/01/31 12:00:00", 1, -385.0, 10011, 6.0, 0, "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", 8.0, 2, "2030/12/17 14:59:59", 109001, "エリコ（バレンタイン）", 24005);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (6, 24, "2019/01/31 12:00:00", 1, 0.0, 10011, 0.0, 0, "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", 0.0, 1, "2030/12/17 14:59:59", 109002, "エリコ（バレンタイン）", 24006);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (7, 24, "2019/01/31 12:00:00", 1, 0.0, 10011, 0.0, 0, "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", 0.0, 1, "2030/12/17 14:59:59", 109002, "エリコ（バレンタイン）", 24007);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (8, 24, "2019/01/31 12:00:00", 1, 0.0, 10011, 0.0, 0, "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", 0.0, 1, "2030/12/17 14:59:59", 109002, "エリコ（バレンタイン）", 24008);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (9, 24, "2019/01/31 12:00:00", 1, 0.0, 10011, 0.0, 0, "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", 0.0, 1, "2030/12/17 14:59:59", 109002, "エリコ（バレンタイン）", 24009);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (10, 24, "2019/01/31 12:00:00", 1, 0.0, 10011, 0.0, 0, "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", 0.0, 1, "2030/12/17 14:59:59", 109002, "エリコ（バレンタイン）", 24010);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 24, "2019/01/31 12:00:00", 1, -385.0, 10011, 2.12, 0, "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", 8.0, 2, "2030/12/17 14:59:59", 109101, "シズル（バレンタイン）", 24011);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 24, "2019/01/31 12:00:00", 5, -385.0, 10011, 4.19, 0, "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", 8.0, 2, "2030/12/17 14:59:59", 109101, "シズル（バレンタイン）", 24012);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (3, 24, "2019/01/31 12:00:00", 2, -385.0, 10011, 2.3, 0, "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", 8.0, 4, "2030/12/17 14:59:59", 109101, "シズル（バレンタイン）", 24013);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (4, 24, "2019/01/31 12:00:00", 1, 0.0, 10011, 0.0, 0, "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", 0.0, 1, "2030/12/17 14:59:59", 109102, "シズル（バレンタイン）", 24014);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (5, 24, "2019/01/31 12:00:00", 5, -385.0, 10011, 5.23, 0, "まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！", 8.0, 2, "2030/12/17 14:59:59", 109101, "シズル（バレンタイン）", 24015);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (6, 24, "2019/01/31 12:00:00", 1, 0.0, 10011, 0.0, 0, "弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪", 0.0, 1, "2030/12/17 14:59:59", 109102, "シズル（バレンタイン）", 24016);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (7, 24, "2019/01/31 12:00:00", 1, -385.0, 10011, 5.01, 0, "あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！", 8.0, 2, "2030/12/17 14:59:59", 109101, "シズル（バレンタイン）", 24017);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (8, 24, "2019/01/31 12:00:00", 1, 0.0, 10011, 0.0, 0, "なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね", 0.0, 1, "2030/12/17 14:59:59", 109102, "シズル（バレンタイン）", 24018);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (9, 24, "2019/01/31 12:00:00", 1, 0.0, 10011, 0.0, 0, "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", 0.0, 1, "2030/12/17 14:59:59", 109102, "シズル（バレンタイン）", 24019);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (10, 24, "2019/01/31 12:00:00", 1, 0.0, 10011, 0.0, 0, "や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪", 0.0, 1, "2030/12/17 14:59:59", 109102, "シズル（バレンタイン）", 24020);
