INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (3, 45, "2015/12/17 15:00:00", 1, -416.5, 0, 5.79, 0, "ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？", 0.0, 2, "2030/12/17 14:59:59", 123001, "アメス", 43006);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 46, "2015/12/17 15:00:00", 1, -371.5, 0, 0.0, 0, "はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。", 0.0, 1, "2030/12/17 14:59:59", 123001, "アメス", 46001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 47, "2015/12/17 15:00:00", 2, -416.5, 0, 0.0, 0, "呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪", 0.0, 2, "2030/12/17 14:59:59", 104901, "シズル", 47001);
